#[cfg(test)]
mod tests {
    use chrono::Utc;
    use rigorix_engine::capacity_ledger::domain::IdempotencyKey;
    use rigorix_engine::effect_commitment::application::{DependentFence, may_release_dependents};
    use rigorix_engine::effect_commitment::domain::{EffectIntent, EffectRecord};
    use uuid::Uuid;

    fn intent() -> EffectIntent {
        EffectIntent::new(
            Uuid::from_u128(1),
            Uuid::from_u128(2),
            1,
            IdempotencyKey::new("intent-key"),
            "payments.charge",
            "args-digest",
            "precondition-digest",
            "authority-digest",
        )
    }

    #[test]
    fn test_dependentfence_is_defined() {
        fn assert_object_safe(_: Option<Box<dyn DependentFence>>) {}
        assert_object_safe(None);
    }

    #[test]
    fn test_dependentfence_interacts_with_effectstate() {
        fn assert_send_sync<T: Send + Sync + ?Sized>() {}
        assert_send_sync::<dyn DependentFence>();

        // F1: a settled or merely dispatched upstream does not fence dependents.
        let dispatched = EffectRecord::begin(intent());
        assert!(may_release_dependents(std::slice::from_ref(&dispatched)));

        let committed = EffectRecord::begin(intent())
            .settle_definite(
                rigorix_engine::effect_commitment::domain::ObservedOutcome::committed(
                    "receipt-1",
                    "readback-1",
                    Utc::now(),
                    "stripe",
                ),
                Utc::now(),
            )
            .unwrap();
        assert!(may_release_dependents(&[committed]));

        // F1: one ambiguous upstream blocks release for the whole set.
        let ambiguous = EffectRecord::begin(intent())
            .mark_ambiguous("response lost", Utc::now())
            .unwrap();
        assert!(!may_release_dependents(&[dispatched, ambiguous]));
    }
}
